plugins {
    alias(libs.plugins.seekmind.android.library)
}

// Licence-token test vectors (testdata/tokens, generated by tools/license/gen_test_vectors.py).
tasks.withType<Test>().configureEach {
    val tokens = rootProject.file("testdata/tokens")
    systemProperty("seekmind.tokens", tokens.path)
    // The keyring a release build ships, alone (the debug one lives in src/debug only).
    systemProperty("seekmind.releaseKeyring", file("src/main/resources/license/keys-release.json").path)
    inputs.dir(tokens).withPropertyName("tokens").withPathSensitivity(PathSensitivity.RELATIVE)
}

dependencies {
    // Header, payload and keyrings of the activation codes (docs/specs/monetisation.md §5).
    implementation(libs.kotlinx.serialization.json)

    testImplementation(libs.junit)
    testImplementation(libs.truth)
}
